import { onMount, useContext } from "solid-js";
import { createMutable } from "solid-js/store";
import { render } from "solid-js/web";

import { Button } from "#core/ui-next/components/button.jsx";
import { Panel } from "#core/ui-next/components/panel.jsx";
import { VSlot } from "#core/ui-next/components/slot.jsx";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { DebugContext, showDebugPanel } from "#core/ui-next/debug/debug-panel.jsx";
import { FocusViewer } from "#core/ui-next/debug/focus-viewer/focus-viewer.jsx";
import { SandboxNavigation } from "#core/ui-next/sandbox/sandbox-navigation.js";

const simpleNav = new SandboxNavigation();

const testModel = createMutable({});

render(() => {
	let ref: HTMLDivElement | undefined;

	const debugContext = useContext(DebugContext);
	debugContext.registerMutableModel("load-screen", testModel);

	onMount(() => {
		simpleNav.setFocus(ref!);
	});

	return (
		<Panel
			name="Scratchpad"
			id="Scratchpad"
			ref={ref}
			class="fullscreen"
		>
			<Tab class="fullscreen flex flex-col">
				<Tab.TabList />
				<Tab.Output />
				<Tab.Item
					name="tab1"
					title={() => "Tab 1"}
					body={() => (
						<VSlot>
							<Button>Tab1 - Button1</Button>
							<Button autoFocus={true}>Tab1 - Button2</Button>
							<Button>Tab1 - Button3</Button>
						</VSlot>
					)}
				/>
				<Tab.Item
					name="tab2"
					title={() => "Tab 2"}
					body={() => (
						<VSlot>
							<Button>Tab2 - Button1</Button>
							<Button>Tab2 - Button2</Button>
							<Button>Tab2 - Button3</Button>
						</VSlot>
					)}
				/>
				<Tab.Item
					name="tab3"
					title={() => "Tab 3"}
					body={() => (
						<VSlot>
							<Button>Tab3 - Button1</Button>
							<Button>Tab3 - Button2</Button>
							<Button>Tab3 - Button3</Button>
						</VSlot>
					)}
				/>
			</Tab>
			<FocusViewer />
		</Panel>
	);
}, document.getElementById("root")!);

showDebugPanel();
